196	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
197	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
198	        if (currentOwner == null) {
199	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
200	        }
201	        currentOwner.setAddress(ownerFieldsDto.getAddress());
202	        currentOwner.setCity(ownerFieldsDto.getCity());
203	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
204	        currentOwner.setLastName(ownerFieldsDto.getLastName());
205	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
206	        this.clinicService.saveOwner(currentOwner);
207	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
208	    }
