235	        PetDto petDto = petMapper.toPetDto(pet);
236	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
237	            .buildAndExpand(pet.getId()).toUri());
238	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
239	    }
