287	    /**
288	     * The maximum number of owners permitted per city. Owner creation is rejected once the
289	     * owner's city already contains this many owners.
290	     */
291	    private static final int MAX_OWNERS_PER_CITY = 50;
292	
293	    /**
294	     * Counts how many existing owners live in the given city, compared case-insensitively.
295	     * This is evaluated before the new owner is persisted, so the owner being created is not
296	     * included in the count.
297	     *
298	     * @param city the new owner's city
299	     * @return the number of existing owners in that city
300	     */
301	    private int countOwnersInCity(String city) {
302	        int count = 0;
303	        for (Owner existing : this.clinicService.findAllOwners()) {
304	            if (city.equalsIgnoreCase(existing.getCity())) {
305	                count++;
306	            }
307	        }
308	        return count;
309	    }
310	
311	    /**
312	     * The maximum number of owners that may be created in a single business day. Owner
313	     * creation is rejected once this many owners already fall on the new owner's adjusted
314	     * business day {@code registrationDate}.
315	     */
316	    private static final int MAX_OWNERS_PER_DAY = 100;
317	
318	    /**
319	     * Rolls a date forward to the next business day: a Saturday or Sunday is moved forward
320	     * to the following Monday, while a weekday is returned unchanged.
321	     *
322	     * @param date the date to adjust
323	     * @return the same date if it is a weekday, otherwise the following Monday
324	     */
325	    private LocalDate toBusinessDay(LocalDate date) {
326	        DayOfWeek dayOfWeek = date.getDayOfWeek();
327	        if (dayOfWeek == DayOfWeek.SATURDAY) {
328	            return date.plusDays(2);
329	        }
330	        if (dayOfWeek == DayOfWeek.SUNDAY) {
331	            return date.plusDays(1);
332	        }
333	        return date;
334	    }
335	
336	    /**
337	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
338	     * registrationDate} rolls forward to the same business day. This is evaluated before the
339	     * new owner is persisted, so the owner being created is not included in the count.
340	     *
341	     * @param businessDay the adjusted business day to count against
342	     * @return the number of existing owners registered on that business day
343	     */
344	    private int countOwnersRegisteredOn(LocalDate businessDay) {
345	        int count = 0;
346	        for (Owner existing : this.clinicService.findAllOwners()) {
347	            LocalDate existingDate = existing.getRegistrationDate();
348	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
349	                count++;
350	            }
351	        }
352	        return count;
353	    }
354	
355	    /**
356	     * The number of owners that may be created on a single business day before a bulk-signup
357	     * warning is raised. Once more than this many owners already fall on the current business
358	     * day, {@code bulkSignupWarning} is reported as {@code true} in the owner response.
359	     */
360	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
361	
362	    /**
363	     * Reports whether an unusually high number of owners have been created for today's business
364	     * day, i.e. whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already fall on
365	     * the business day that {@code LocalDate.now()} rolls forward to.
366	     *
367	     * @return {@code true} once more than 80 owners have been created today, otherwise {@code false}
368	     */
369	    private boolean isBulkSignupDay() {
370	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > BULK_SIGNUP_WARNING_THRESHOLD;
371	    }
372	
373	    /**
374	     * Builds the customer code for a newly created owner, formatted
375	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first
376	     * three letters of the city, {@code LAST3} the upper-cased first three letters of
377	     * the last name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal
378	     * to one more than the number of owners already in that city.
379	     *
380	     * @param city     the owner's city
381	     * @param lastName the owner's last name
382	     * @return the assigned customer code (e.g. {@code 'SYD-SMI-0007'})
383	     */
384	    private String nextCustomerCode(String city, String lastName) {
385	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
386	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
387	        int sequence = 1;
388	        for (Owner existing : this.clinicService.findAllOwners()) {
389	            if (city.equalsIgnoreCase(existing.getCity())) {
390	                sequence++;
391	            }
392	        }
393	        return String.format("%s-%s-%04d", city3, last3, sequence);
394	    }
395	
396	    /**
397	     * Builds the membership number for a newly created owner, formatted
398	     * {@code '<customerCode>-M<YY>'} where {@code customerCode} is the owner's assigned
399	     * customer code and {@code YY} is the last two digits of the owner's registration
400	     * date year, zero-padded to two digits.
401	     *
402	     * @param customerCode     the owner's assigned customer code (e.g. {@code 'SYD-SMI-0007'})
403	     * @param registrationDate the owner's registration date
404	     * @return the assigned membership number (e.g. {@code 'SYD-SMI-0007-M26'})
405	     */
406	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
407	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
408	    }
409	
410	    /**
411	     * Counts how many existing owners share the given first and last name, compared
412	     * case-insensitively. This is evaluated before the new owner is persisted, so the
413	     * owner being created is not included in the count.
414	     *
415	     * @param firstName the new owner's first name
416	     * @param lastName  the new owner's last name
417	     * @return the number of existing owners with the same first and last name
418	     */
419	    private int countNamesakes(String firstName, String lastName) {
420	        int count = 0;
421	        for (Owner existing : this.clinicService.findAllOwners()) {
422	            if (firstName.equalsIgnoreCase(existing.getFirstName())
423	                && lastName.equalsIgnoreCase(existing.getLastName())) {
424	                count++;
425	            }
426	        }
427	        return count;
428	    }
429	
430	    /**
431	     * Canonical expansions applied to common street-type abbreviations during address
432	     * normalization. Keys and values are upper-cased so the lookup runs after the address
433	     * has itself been upper-cased.
434	     */
435	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
436	        "ST", "STREET",
437	        "RD", "ROAD",
438	        "AVE", "AVENUE");
439	
440	    /**
441	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
442	     * every run of internal whitespace is collapsed to a single space, the result is
443	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
444	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
445	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
446	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
447	     * returned and compared for household duplicates; an address that is blank once
448	     * normalized fails the required-field check.
449	     *
450	     * @param address the raw address value supplied by the client
451	     * @return the normalized address (empty string when {@code address} is null or blank)
452	     */
453	    private static String normalizeAddress(String address) {
454	        if (address == null) {
455	            return "";
456	        }
457	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
458	        if (collapsed.isEmpty()) {
459	            return "";
460	        }
461	        StringBuilder normalized = new StringBuilder(collapsed.length());
462	        for (String token : collapsed.split(" ")) {
463	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
464	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
465	            if (normalized.length() > 0) {
466	                normalized.append(' ');
467	            }
468	            normalized.append(expanded != null ? expanded : token);
469	        }
470	        return normalized.toString();
471	    }
472	
473	    /**
474	     * Normalizes a last name or address for household-duplicate comparison: leading and
475	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
476	     * single space and the result is lower-cased. Two owners are considered to share a
477	     * household when both their last names and addresses produce the same key.
478	     *
479	     * @param value the raw last name or address value
480	     * @return the normalized comparison key (empty string when {@code value} is null)
481	     */
482	    private static String householdKey(String value) {
483	        if (value == null) {
484	            return "";
485	        }
486	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
487	    }
488	
489	    /**
490	     * Derives the stable shared household identifier for the given normalized last name
491	     * and address keys. The identifier is deterministic — the same household (same
492	     * {@link #householdKey normalized} last name and address) always maps to the same
493	     * value — so every owner who joins a household is assigned an identical id. It is the
494	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
495	     * '<lastNameKey>|<addressKey>'}.
496	     *
497	     * @param lastNameKey the normalized last name key
498	     * @param addressKey  the normalized address key
499	     * @return the shared household identifier
500	     */
501	    private static String householdId(String lastNameKey, String addressKey) {
502	        String source = lastNameKey + "|" + addressKey;
503	        try {
504	            byte[] digest = MessageDigest.getInstance("SHA-256")
505	                .digest(source.getBytes(StandardCharsets.UTF_8));
506	            StringBuilder hex = new StringBuilder(digest.length * 2);
507	            for (byte b : digest) {
508	                hex.append(String.format("%02x", b));
509	            }
510	            return hex.substring(0, 12).toUpperCase();
511	        } catch (NoSuchAlgorithmException e) {
512	            throw new IllegalStateException("SHA-256 not available", e);
513	        }
514	    }
515	
516	    /**
517	     * Builds the derived duplicate-detection identity key from an owner's normalized
518	     * telephone, email and household id, formatted {@code
519	     * '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Two owners are
520	     * duplicates only when their whole identity keys are equal; because the telephone is
521	     * part of the key, members of the same household with different telephones produce
522	     * different keys and are both allowed.
523	     *
524	     * @param normalizedTelephone the E.164 telephone (may be {@code null})
525	     * @param email               the normalized (lower-cased) email, or {@code null} when absent
526	     * @param householdId         the shared household id, or {@code null} when the owner is not in a household
527	     * @return the identity key string
528	     */
529	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
530	        return (normalizedTelephone == null ? "" : normalizedTelephone)
531	            + "|" + (email == null ? "" : email)
532	            + "|" + (householdId == null ? "" : householdId);
533	    }
534	
535	    /**
536	     * Normalizes an existing owner's stored email for identity-key comparison: trimmed and
537	     * lower-cased, mirroring {@link #normalizeEmail} without re-validating syntax. Returns
538	     * {@code null} when the owner has no email.
539	     *
540	     * @param email the existing owner's stored email (may be {@code null})
541	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is null
542	     */
543	    private static String emailForKey(String email) {
544	        return email == null ? null : email.trim().toLowerCase();
545	    }
546	
547	    /**
548	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
549	     * and brackets are stripped. When the number already carries a leading {@code '+'}
550	     * and country code these are kept; a number written in national trunk form (a leading
551	     * {@code '0'}) is treated as Australian, so the {@code '0'} is dropped and country code
552	     * {@code '+61'} prepended; any other bare number is treated as a NANP number and country
553	     * code {@code '+1'} is prepended. The resulting number must have between 8 and 15 digits
554	     * after the {@code '+'}, and its national-number length must be valid for the detected
555	     * country code (see {@link #hasValidNationalLength}).
556	     *
557	     * @param telephone the raw telephone value supplied by the client
558	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
559	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
560	     */
561	    private static String toE164(String telephone) {
562	        if (telephone == null) {
563	            return null;
564	        }
565	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
566	        String digits;
567	        if (cleaned.startsWith("+")) {
568	            digits = cleaned.substring(1);
569	        } else if (cleaned.startsWith("0")) {
570	            digits = "61" + cleaned.substring(1);
571	        } else {
572	            digits = "1" + cleaned;
573	        }
574	        if (!digits.matches("[0-9]{8,15}")) {
575	            return null;
576	        }
577	        if (!hasValidNationalLength(digits)) {
578	            return null;
