35	     * that falls inside a known region's range, that region is returned; otherwise fall back
36	     * to the city-to-region table. Returns {@code "UNKNOWN"} when neither resolves a region.
37	     */
38	    public static String forCityAndPostcode(String city, String postcode) {
39	        String byPostcode = forPostcode(postcode);
40	        return byPostcode != null ? byPostcode : forCity(city);
