43	    /**
44	     * Return the canonical region whose postcode range contains {@code postcode}, or
45	     * {@code null} when the postcode is absent, malformed, or in no known range.
46	     */
47	    private static String forPostcode(String postcode) {
48	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
49	            return null;
50	        }
51	        int value = Integer.parseInt(postcode);
52	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
53	            int[] range = entry.getValue();
54	            if (value >= range[0] && value <= range[1]) {
55	                return entry.getKey();
56	            }
57	        }
58	        return null;
59	    }
